cat > /tmp/analyze_growth.pl << 'EOF'
use strict;
use warnings;

# Data from the test output
my @data = (
    [10,  0.147],
    [25,  0.744],
    [50,  1.695],
    [75,  2.966],
    [100, 4.801],
    [150, 7.840],
    [200, 14.354],
);

print "Lines\tTime(s)\tTime/n\tTime/n²\tTime/n³\n";
print "=" x 60, "\n";

foreach my $point (@data) {
    my ($n, $t) = @$point;
    my $t_per_n = $t / $n;
    my $t_per_n2 = $t / ($n * $n);
    my $t_per_n3 = $t / ($n * $n * $n);

    printf "%d\t%.3f\t%.4f\t%.6f\t%.8f\n", 
           $n, $t, $t_per_n, $t_per_n2, $t_per_n3;
}

print "\nRatios (should be constant for the correct complexity):\n";
print "=" x 60, "\n";

for (my $i = 1; $i < @data; $i++) {
    my ($n1, $t1) = @{$data[$i-1]};
    my ($n2, $t2) = @{$data[$i]};

    my $n_ratio = $n2 / $n1;
    my $t_ratio = $t2 / $t1;

    # If O(n), t_ratio should equal n_ratio
    # If O(n²), t_ratio should equal n_ratio²
    # If O(n³), t_ratio should equal n_ratio³

    my $expected_linear = $n_ratio;
    my $expected_quadratic = $n_ratio ** 2;
    my $expected_cubic = $n_ratio ** 3;

    printf "From %d to %d lines (%.2fx):\n", $n1, $n2, $n_ratio;
    printf "  Time ratio: %.2fx\n", $t_ratio;
    printf "  Expected if O(n):  %.2fx (diff: %.2f)\n", 
           $expected_linear, abs($t_ratio - $expected_linear);
    printf "  Expected if O(n²): %.2fx (diff: %.2f)\n", 
           $expected_quadratic, abs($t_ratio - $expected_quadratic);
    printf "  Expected if O(n³): %.2fx (diff: %.2f)\n\n", 
           $expected_cubic, abs($t_ratio - $expected_cubic);
}
EOF
plenv exec perl /tmp/analyze_growth.pl

